 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(build());select(0);}
 private View build(){ScrollView s=new ScrollView(this);s.setBackgroundColor(Color.rgb(242,246,250));LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(14),dp(16),dp(14),dp(24));s.addView(r);r.addView(t("VISUAL ENGINEERING LAB",24,true));r.addView(t("Teknik illüstrasyon + FBD • ölçü, yük ve kritik bölgeler canlı güncellenir",14,false));LinearLayout tabs=new LinearLayout(this);for(int i=0;i<3;i++){final int x=i;Button b=new Button(this);b.setText(MODES[i]);b.setAllCaps(false);b.setOnClickListener(v->select(x));tabs.addView(b,new LinearLayout.LayoutParams(0,dp(50),1));}r.addView(tabs);for(int i=0;i<6;i++){in[i]=new EditText(this);in[i].setSingleLine();in[i].setInputType(2|8192|16384);in[i].addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){if(d!=null){d.v=vals();d.invalidate();}}public void afterTextChanged(Editable e){}});r.addView(in[i],new LinearLayout.LayoutParams(-1,dp(52)));}TextView cap=t("CANLI MÜHENDİSLİK GÖRSELİ",12,true);cap.setTextColor(Color.rgb(30,64,175));r.addView(cap);d=new Diagram();r.addView(d,new LinearLayout.LayoutParams(-1,dp(470)));Button old=new Button(this);old.setText("TÜM MAKİNE ELEMANLARI GALERİSİ →");old.setAllCaps(false);old.setOnClickListener(v->startActivity(new android.content.Intent(this,MachineElementStudioActivity.class)));r.addView(old);return s;}
 private void select(int m){mode=m;for(int i=0;i<6;i++){in[i].setHint(HINTS[m][i]);in[i].setVisibility(HINTS[m][i].isEmpty()?View.GONE:View.VISIBLE);in[i].setText("");}if(d!=null){d.v=vals();d.invalidate();}}
